from util import chunk

# aliasing check
data = [[1],[2],[3]]
out = chunk(data, 2)
print('out=', out)
out[0][0].append(99)
print('data after mutating out element=', data)

# size bool
print('size True ->', chunk([1,2,3], True))
try:
    print('size False ->', chunk([1,2,3], False))
except Exception as e:
    print('size False raised', type(e).__name__, e)

# size float
try:
    print(chunk([1,2,3,4,5], 2.0))
except Exception as e:
    print('size 2.0 raised', type(e).__name__, e)

try:
    print(chunk([1,2,3,4,5], 2.5))
except Exception as e:
    print('size 2.5 raised', type(e).__name__, e)

# items types
try:
    print(chunk((1,2,3), 2))
except Exception as e:
    print('tuple raised', type(e).__name__, e)

try:
    print(chunk('abcdef', 2))
except Exception as e:
    print('str raised', type(e).__name__, e)

def gen():
    yield 1; yield 2; yield 3
try:
    print(chunk(gen(), 2))
except Exception as e:
    print('generator raised', type(e).__name__, e)

try:
    print(chunk(None, 2))
except Exception as e:
    print('None items raised', type(e).__name__, e)

# huge size
print('huge size ->', chunk([1,2,3], 10**9))
"

